const columns = [
  "id", "label", "code", "title", "categories", "createdAt", "updatedAt", "logo",
  "hidden", "highlights", "shortAbout", "address", "locationLng", "locationLat",
  "invitationCode", "isActive", "emails", "phones", "domain"
];

if (rows.length !== 89) throw new Error(`Expected 89 provider rows, got ${rows.length}`);
if (new Set(rows.map((row) => row.id)).size !== rows.length) throw new Error("Provider IDs are not unique");

const cellValue = (value) => {
  if (value === null || value === undefined) return "";
  if (Array.isArray(value) || (typeof value === "object" && value !== null)) return JSON.stringify(value);
  return value;
};

const matrix = [columns, ...rows.map((row) => columns.map((column) => cellValue(row[column])))];

const workbook = Workbook.create();
const sheet = workbook.worksheets.add("Providers");
sheet.getRangeByIndexes(0, 0, matrix.length, columns.length).values = matrix;
sheet.freezePanes.freezeRows(1);
sheet.getRange("A1:S1").format = {
  fill: "#0F766E",
  font: { bold: true, color: "#FFFFFF" },
};
sheet.getRange("A1:S90").format.wrapText = false;
sheet.getRange("M2:N90").format.numberFormat = "0.0000000000000";

const inspection = await workbook.inspect({
  kind: "region",
  sheetId: "Providers",
  range: "A1:S6",
  maxChars: 4000,
  tableMaxRows: 6,
  tableMaxCols: 19,
  tableMaxCellChars: 80,
});

const quoteCsv = (value) => {
  if (value === null || value === undefined) return "";
  const text = String(value);
  return `"${text.replaceAll('"', '""')}"`;
};
const csvText = matrix.map((row) => row.map(quoteCsv).join(",")).join("\r\n") + "\r\n";

const outputPath = "/Users/ahmedelghannam/projects/playground/eign-newsletter/outputs/supabase/kattch-prod-providers-2026-08-30.csv";
await fs.mkdir(path.dirname(outputPath), { recursive: true });
await fs.writeFile(outputPath, csvText, "utf8");

const imported = await Workbook.fromCSV(csvText, { sheetName: "Providers" });
const importedCheck = await imported.inspect({
  kind: "region",
  sheetId: "Providers",
  range: "A1:S6",
  maxChars: 4000,
  tableMaxRows: 6,
  tableMaxCols: 19,
  tableMaxCellChars: 80,
});
const fullImportCheck = await imported.inspect({
  kind: "region",
  sheetId: "Providers",
  range: "A1:S90",
  maxChars: 1200,
  tableMaxRows: 2,
  tableMaxCols: 19,
  tableMaxCellChars: 30,
});

const fileStat = await fs.stat(outputPath);
console.log(JSON.stringify({
  outputPath,
  providerRows: rows.length,
  columns: columns.length,
  uniqueIds: new Set(rows.map((row) => row.id)).size,
  bytes: fileStat.size,
  workbookInspection: inspection.ndjson,
  csvRoundTripInspection: importedCheck.ndjson,
  fullCsvInspection: fullImportCheck.ndjson,
}));
